static inline lua_Value lua_tbl_isfrozen(lua_Value table) {
    if (table.type != VAL_TABLE) return lua_val_from_bool(false);
    lua_Table* t = (lua_Table*)table.as.tval;
    return lua_val_from_bool(t && t->frozen);
}

